[{"order":1,"type":"heading","text":"Local Caching in iOS: Keychain, UserDefaults, FileManager, and SQLite"},{"order":2,"type":"paragraph","text":"Effective local caching is essential for building responsive, reliable, and offline-capable iOS applications. Choosing the right storage mechanism depends entirely on the nature and sensitivity of your data. This tutorial explores the four primary local caching solutions in iOS using Swift: UserDefaults, Keychain, FileManager, and SQLite."},{"order":3,"type":"subheading","text":"1. UserDefaults: Simple Key-Value Storage"},{"order":4,"type":"paragraph","text":"UserDefaults is designed for storing small amounts of user preferences and application configurations. It persists data as a property list (.plist) file on disk. Never store sensitive data like passwords or tokens here."},{"order":5,"type":"code","text":"import Foundation

class UserPreferences {
    private let defaults = UserDefaults.standard
    private let usernameKey = "username"

    var username: String? {
        get { return defaults.string(forKey: usernameKey) }
        set { defaults.set(newValue, forKey: usernameKey) }
    }
}"},{"order":6,"type":"subheading","text":"2. Keychain: Secure Data Storage"},{"order":7,"type":"paragraph","text":"The iOS Keychain provides encrypted storage for sensitive data such as passwords, cryptographic keys, and session tokens. Data stored in the Keychain persists even after the app is uninstalled."},{"order":8,"type":"code","text":"import Foundation
import Security

class KeychainService {
    static func save(key: String, data: Data) -> OSStatus {
        let query = [
            kSecClass: kSecClassGenericPassword,
            kSecAttrAccount: key,
            kSecValueData: data
        ] as CFDictionary

        SecItemDelete(query)
        return SecItemAdd(query, nil)
    }

    static func load(key: String) -> Data? {
        let query = [
            kSecClass: kSecClassGenericPassword,
            kSecAttrAccount: key,
            kSecReturnData: true,
            kSecMatchLimit: kSecMatchLimitOne
        ] as CFDictionary

        var dataTypeRef: AnyObject?
        let status = SecItemCopyMatching(query, &dataTypeRef)

        if status == errSecSuccess {
            return dataTypeRef as? Data
        }
        return nil
    }
}"},{"order":9,"type":"subheading","text":"3. FileManager: Handling Files and Large Caches"},{"order":10,"type":"paragraph","text":"FileManager is used for reading and writing files directly to the device directory. It is the ideal mechanism for caching large assets such as images, JSON payloads, or documents inside the Caches or Documents directories."},{"order":11,"type":"code","text":"import Foundation

class FileCacheManager {
    private static var cacheDirectory: URL {
        return FileManager.default.urls(for: .cachesDirectory, in: .userDomainMask)[0]
    }

    static func save(data: Data, fileName: String) {
        let fileURL = cacheDirectory.appendingPathComponent(fileName)
        try? data.write(to: fileURL)
    }

    static func load(fileName: String) -> Data? {
        let fileURL = cacheDirectory.appendingPathComponent(fileName)
        return try? Data(contentsOf: fileURL)
    }
}"},{"order":12,"type":"subheading","text":"4. SQLite: Structured Relational Caching"},{"order":13,"type":"paragraph","text":"When your app requires complex relational queries, indexing, and fast lookups of structured records, SQLite is the best approach. While you can use raw C-APIs, wrappers like SQLite.swift or GRDB simplify implementation significantly."},{"order":14,"type":"bullet_point","text":"UserDefaults: Use for lightweight configuration flags and primitives."},{"order":15,"type":"bullet_point","text":"Keychain: Use exclusively for authentication tokens and credentials."},{"order":16,"type":"bullet_point","text":"FileManager: Use for binary assets, images, and large documents."},{"order":17,"type":"bullet_point","text":"SQLite: Use for heavy relational data models and offline-first database syncs."}]
